        dict(dimension='Engagement',responsibility='Transformer une intention planifiée en ordre ferme selon le type d’Order.',existing_behaviors=['BHV036']),
        dict(dimension='Protection contre la réoptimisation',responsibility='Définir et appliquer les éléments gelés et les conditions de leur révision.',existing_behaviors=['BHV037']),
        dict(dimension='Autorisation de prise en charge',responsibility='Autoriser le traitement d’une part de demande, individuellement ou collectivement.',existing_behaviors=['BHV039']),
