    review['lifecycle_dimensions_U423']=dict(status='proposed',source_refs=['U421','U422','U423','ELM250','CMP161'],preferred_direction='Conserver une capacité Order Lifecycle Management ; revoir ses comportements par dimension métier plutôt que déplacer la capacité entière ou créer un comportement pour chaque état.',definition_proposed='Gouverner les évolutions autorisées des Orders selon leurs dimensions de maturité, d’engagement, de protection et de prise en charge, en préservant la cohérence entre contenu applicable, modifications en préparation et réalisations acquises.',dimension_examples=dims,benefit='Rendre possible une commande engagée et partiellement libérée dont une modification se prépare, sans confondre autorisation, suspension, protection et réalisation.',boundaries=['Le domaine courant de Lifecycle reste D04. Une capacité et ses comportements gardent un parent unique ; ils ne sont pas distribués artificiellement entre D03 et D04.', 'D03 mobilise les comportements de Lifecycle pour mettre en action le scénario retenu. Ce lien de responsabilité ne présume pas un composant logiciel mutualisé.', 'Les politiques, décisions et calculs de D03 restent distincts des transitions appliquées par Lifecycle.', 'D06 orchestre les services et fournit les faits de réalisation ; une autorisation ne prouve pas un démarrage.', 'Order Archiving et Order Structuring restent distincts en D03, conformément aux choix acquis.', 'Un tableau de dimensions ne vaut pas liste de comportements adoptée ; aucune sous-décomposition, duplication ni fusion implicite.', 'Les contraintes entre dimensions s’apprécient par type, version, ligne et quantité. Une révision ne permet pas de réécrire les réalisations acquises.'],market_comparisons=[dict(vendor='Microsoft',product='Dynamics 365 Supply Chain Management',title='Purchase order overview',url='https://learn.microsoft.com/en-us/dynamics365/supply-chain/procurement/purchase-order-overview',version='2026-09-08',locator='Purchase order statuses',consulted_on='2026-09-19',finding='Purchase order status, Document status et Approval status coexistent sur une commande.',relationship='Appui méthodologique',limits='Données et processus produit : ne prouvent pas une capacité Microsoft découpée selon nos dimensions.'),dict(vendor='Microsoft',product='Dynamics 365 Intelligent Order Management',title='State framework architecture',url='https://learn.microsoft.com/en-us/dynamics365/intelligent-order-management/state-framework',version='2026-01-30',locator='Entity State and State Reason columns ; State Transition table',consulted_on='2026-09-19',finding='États, motifs et transitions sont explicités ; la possibilité de modification est représentée par ReadOnly.',relationship='Appui méthodologique',limits='Documentation avec réserve de préversion ; framework de réalisation et non cartographie business. Aucune indépendance absolue des dimensions démontrée.')],catalogue_unchanged=True,catalogue_sha256=digest)
